def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    anchors=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==4]
    for r,c in anchors:
        for dr in (-1,0,1):
            rr=r+dr
            if 0<=rr<h: out[rr][c]=5
    return out
